  async createProject(name: string, projectId?: string): Promise<unknown> {
    const clean = name.trim(); if (!clean) throw new Error('Project name is required');
    if(projectId&&(!/^prj_[0-9a-f-]{36}$/.test(projectId)))throw new Error('Invalid project ID');
    const project=await this.store.mutate(s => { const nextId=projectId??id('prj');if(s.projects.some(p=>p.id===nextId))throw Object.assign(new Error('Project already exists'),{statusCode:409});const defaults:Record<string,RoleConfig>={};const project = { id: nextId, name: clean, status: 'active' as const, defaultRoleConfigs: defaults, createdAt: now(), tasks: [] }; s.projects.push(project); s.events.push(event('project.created','project',project.id,{name:clean})); return project; });
    if(this.hindsight?.ensureBank)void this.hindsight.ensureBank((project as any).id).then(result=>this.memoryServiceState=result.status==='ready'?'ready':'degraded').catch(()=>this.memoryServiceState='degraded');
    return project;
  }
  async deleteProject(projectId:string):Promise<{deleted:true;projectId:string;taskCount:number;runCount:number}>{
    if(this.projectScopeId&&projectId!==this.projectScopeId)throw Object.assign(new Error('Project not found'),{statusCode:404});
    return this.store.mutate(s=>{
      const project=must(s.projects.find(p=>p.id===projectId),'Project');
      const reason=projectDeletionBlocker(project,this.projectPlannerTurns.has(projectId),this.taskStarts,this.automaticRuns);
      if(reason)throw Object.assign(new Error(`Project cannot be deleted because ${reason}`),{statusCode:409});
      const runCount=project.tasks.reduce((sum,task)=>sum+task.runs.length,0),taskCount=project.tasks.length;
      // Collect all entity IDs belonging to this project so legacy events can be pruned.
      const taskIds=new Set(project.tasks.map(t=>t.id));
      const runIds=new Set(project.tasks.flatMap(t=>t.runs.map(r=>r.id)));
      const assignmentIds=new Set(project.tasks.flatMap(t=>t.runs.flatMap(r=>r.assignments.map(a=>a.id))));
      const guidanceIds=new Set(project.tasks.flatMap(t=>t.runs.flatMap(r=>r.guidance.map(g=>g.id))));
      const sessionLocalIds=new Set(project.tasks.flatMap(t=>t.runs.flatMap(r=>[
        r.sessions?.planner?.localId, r.sessions?.orchestrator?.localId,
        ...(r.sessionHistory??[]).map(sess=>sess.localId),
      ].filter((v):v is string=>typeof v==='string'))));
      s.events=s.events.filter(e=>{
        if(e.entityId===projectId)return false;
        if(taskIds.has(e.entityId))return false;
        if(runIds.has(e.entityId))return false;
        if(assignmentIds.has(e.entityId))return false;
        if(guidanceIds.has(e.entityId))return false;
        if(sessionLocalIds.has(e.entityId))return false;
        if(e.data.projectId===projectId)return false;
        if(typeof e.data.taskId==='string'&&taskIds.has(e.data.taskId))return false;
        if(typeof e.data.runId==='string'&&runIds.has(e.data.runId))return false;
        return true;
      });
      s.projects=s.projects.filter(p=>p.id!==projectId);
      s.events.push(event('project.deleted','project',projectId,{taskCount,runCount,workspaceConfigurationRemoved:true}));
      return {deleted:true,projectId,taskCount,runCount};
    });
  }
  async deleteTask(taskId:string):Promise<{deleted:true;taskId:string;runCount:number}>{
    return this.store.mutate(s=>{
      const {project,task}=this.findTask(s,taskId);
      const dependent=project.tasks.find(candidate=>candidate.id!==taskId&&(candidate.dependsOn??[]).includes(taskId));
      if(dependent)throw Object.assign(new Error(`Task cannot be deleted because task “${dependent.title}” depends on it`),{statusCode:409});
      const reason=taskDeletionBlocker(task,this.taskStarts.has(taskId),this.automaticRuns);
      if(reason)throw Object.assign(new Error(`Task cannot be deleted because ${reason}`),{statusCode:409});
      const runIds=task.runs.map(run=>run.id);
      project.tasks=project.tasks.filter(item=>item.id!==taskId);
      s.events.push(event('task.deleted','task',taskId,{projectId:project.id,runCount:runIds.length}));
      return {deleted:true,taskId,runCount:runIds.length};
    });
  }
