      if(run.controller?.active)throw Object.assign(new Error('Human acceptance is available after the controller reaches a decision checkpoint'),{statusCode:409});
      if(typeof input.approved!=='boolean')throw Object.assign(new Error('An explicit human approval or rejection decision is required'),{statusCode:400});
      if(run.approval)throw Object.assign(new Error('A human decision is final for this run'),{statusCode:409});
      if(!run.workerEvidence?.scopeVerified||run.workerEvidence.acceptance!=='not_decided'||!run.validation||run.validation.status!=='passed'||!run.validation.observations?.length||!run.reviewerRecommendation)throw Object.assign(new Error('Human decision requires verified Worker scope, passing controller-observed validation, and a recorded independent Reviewer recommendation'),{statusCode:409});
