      const reviewerModelBindingMatches=!!reviewer&&reviewerAssignmentModelEvidence(reviewer)&&recommendation.harnessId===reviewerHarness&&recommendation.model===reviewer.requestedConfig.model&&(reviewer.actualConfig?.model?recommendation.actualModel===reviewer.actualConfig.model:reviewer.actualModelStatus==='unavailable'&&recommendation.actualModel===undefined);
      if(!reviewer||reviewer.roleId!=='reviewer'||reviewer.status!=='succeeded'||!reviewerModelBindingMatches||!reviewer.responseId||!reviewer.sessionId||reviewer.responseId!==recommendation.responseId||reviewer.sessionId!==recommendation.sessionId||recommendation.reviewMode!=='read_only'||recommendation.mutationAttempted!==false||reviewer.reviewerExecution?.mode!=='read_only'||reviewer.reviewerExecution.mutationAttempted||!reviewerEvidenceMatches||reviewer.responseId===run.workerEvidence.responseId||reviewer.sessionId===run.assignments.find(a=>a.id===run.workerEvidence?.workerAssignmentId)?.sessionId)throw Object.assign(new Error('Human decision requires a succeeded Reviewer bound to the current controller evidence with distinct response and session identifiers'),{statusCode:409});
      const completedWorkers=this.currentSuccessfulWorkers(run);
