      if(input.evidenceDigest.toLowerCase()!==evidenceDigest)throw Object.assign(new Error('The evidence changed since you reviewed it; refresh and review the current result before deciding.'),{statusCode:409});
      const accepted={id:id('approval'),approved:input.approved,decision:input.approved?'approved' as const:'rejected' as const,evidenceCommit:run.workerEvidence.pinnedBaseCommit,evidenceDigest,rationale:input.rationale?.trim(),createdAt:now()};run.approval=accepted;run.workerEvidence.acceptance=input.approved?'accepted':'rejected';run.status=input.approved?'completed':'failed';
