    if(initial.orchestratorBlock||this.blockResumeInFlight.has(runId))throw Object.assign(new Error('This run is blocked or resuming Orchestrator prerequisites and cannot be promoted'),{statusCode:409});
    if(!initial.approval?.approved||initial.approval.decision!=='approved')throw Object.assign(new Error('An approved human decision is required before promotion'),{statusCode:409});
    if(initial.promotion?.status==='abandoned')throw Object.assign(new Error('This approved result was abandoned and cannot be promoted'),{statusCode:409});
    if(input.destinationBranch!==undefined&&typeof input.destinationBranch!=='string')throw Object.assign(new Error('Promotion destination branch must be a string'),{statusCode:400});
