    const reverified=await verifyWorkerSnapshot({repoPath,pinnedBaseCommit:run.pinnedBaseCommit,allowedScope:configuredScope,envelope:{complete:true,base_commit:w.pinnedBaseCommit,entries,errors:[]}}) as WorkerEvidence;
