export function workerProposalScopeIssue(
  targetFiles:string[]|undefined,
  allowedScope:string[],
  requireExactTarget=false,
  baseFilePaths:string[]=[],
  legacyTaskText?:string
):string|undefined {
  if(!allowedScope.length)return 'Worker proposal has no configured allowed scope';
  let files=targetFiles;
  if(files===undefined) {
    if(!requireExactTarget) {
      // Non-AGY legacy: no targetFiles provided — post-diff verification enforces scope.
      return undefined;
    }
    // AGY legacy: extract explicit "Target file:" lines from the task text only.
    const extracted:string[]=[];
    if(legacyTaskText) {
      for(const match of legacyTaskText.matchAll(/\bTarget file:\s*([^\s,;]+)/gi)) {
        const path=(match[1]??'').replace(/[.!]$/,'').trim();
        if(path)extracted.push(path);
      }
    }
    if(!extracted.length)return 'Antigravity Worker requires a Target file: exact/relative/path.ext in its task';
    files=extracted;
  }
  if(!files.length&&requireExactTarget)return 'Antigravity Worker requires a Target file: exact/relative/path.ext in its task';
  for(const raw of files) {
    const path=raw.replace(/^\.\//,'').replace(/\\/g,'/');
    if(path.startsWith('/'))return `Worker proposal references a path outside the allowed scope: ${path}`;
    if(path.split('/').some(part=>part==='..'))return `Worker proposal references a path outside the allowed scope: ${path}`;
    if(!scopeContainedBy(path,allowedScope))return `Worker proposal references a path outside the allowed scope: ${path}`;
    if(requireExactTarget) {
      if(!path||path.endsWith('/')||allowedScope.some(root=>root.endsWith('/')&&path===root.replace(/\/$/,'')))
        return `Antigravity Worker requires an exact target file inside allowed scope: ${path}`;
    }
  }
  return undefined;
}
